//! Cargo-driven `wbemprox.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6d2d0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe54000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe54000000u64)),
        o => panic!("wbemprox-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:iphlpapi", "import:oleaut32", "import:ole32", "import:advapi32", "import:user32", "import:gdi32", "import:version", "import:winspool", "import:ws2_32", "import:rpcrt4", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:iphlpapi", "import:oleaut32", "import:ole32", "import:advapi32", "import:user32", "import:gdi32", "import:version", "import:winspool", "import:ws2_32", "import:rpcrt4", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:iphlpapi", "import:oleaut32", "import:ole32", "import:advapi32", "import:user32", "import:gdi32", "import:version", "import:winspool", "import:ws2_32", "import:rpcrt4", "import:setupapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/wbemprox",
        "dll/win32/wbemprox",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x0A00",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("wbemprox_shims", &["dll/win32/wbemprox/builtin.c", "dll/win32/wbemprox/class.c", "dll/win32/wbemprox/main.c", "dll/win32/wbemprox/process.c", "dll/win32/wbemprox/qualifier.c", "dll/win32/wbemprox/query.c", "dll/win32/wbemprox/reg.c", "dll/win32/wbemprox/security.c", "dll/win32/wbemprox/service.c", "dll/win32/wbemprox/services.c", "dll/win32/wbemprox/sysrestore.c", "dll/win32/wbemprox/table.c", "dll/win32/wbemprox/wbemlocator.c", "dll/win32/wbemprox/guid.c", "dll/win32/wbemprox/wql.tab.c"])
        .rc("dll/win32/wbemprox/wbemprox.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/wbemprox/wbemprox.spec", "wbemprox.dll")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .import_lib("win32ss/printing/base/winspool/winspool.spec", "winspool.drv", "winspool")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
